"""Reusable commercial offer; one tax-inclusive total shared by all sales pages."""
from urllib.parse import quote
from build import t

OFFER_TOTAL = '997.99'


def enquiry_link():
    return f'<a class="button offer-enquiry" href="/contacto/?source=proforma">{t("Quiero esta experiencia ↗", "I want this experience ↗")}</a>'



def offer(show_intro=True):
    rows = [
        ('01', 'Tu marca, tu proyecto', 'Your brand, your project', 'Sitio web adaptado a la identidad de un proyecto inmobiliario, con presentación comercial en español e inglés.', 'A website tailored to one real estate project’s identity, with a commercial presentation in Spanish and English.'),
        ('02', 'Arquitectura que se explora', 'Architecture to explore', 'Una vista exterior 3D interactiva, puntos de interés e iluminación, con un modelo compatible suministrado por tu equipo.', 'One interactive 3D exterior, points of interest and lighting, using a compatible model supplied by your team.'),
        ('03', 'Cada vivienda, en contexto', 'Every home in context', 'Selector por piso, tipología y disponibilidad para hasta 100 unidades, con una carga inicial de inventario.', 'Selection by floor, apartment type and availability for up to 100 units, including one initial inventory import.'),
        ('04', 'Interiores por tipología', 'Interiors by apartment type', 'Hasta 2 tipologías interiores con navegación por ambientes, a partir de modelos compatibles suministrados y aprobados.', 'Up to 2 interior apartment types with room navigation, using supplied, compatible and approved models.'),
        ('05', 'Una consulta mejor preparada', 'A better-informed enquiry', 'Contacto comercial con los datos de la unidad elegida para que tu equipo pueda continuar la conversación.', 'A sales enquiry carrying the selected unit’s details, so your team can continue the conversation.'),
        ('06', 'Listo para compartir', 'Ready to share', 'Adaptación a móvil y escritorio, revisión del recorrido y publicación en el dominio acordado.', 'Mobile and desktop layouts, journey review and publication on the agreed domain.'),
    ]
    scope = ''.join(f'<li><span class="scope-number">{n}</span><div><h3>{t(es,en)}</h3><p>{t(desc,desc_en)}</p></div><span class="scope-check" aria-hidden="true">✓</span></li>' for n,es,en,desc,desc_en in rows)
    heading = f'''<div class="offer-heading"><span class="eyebrow">{t('UNA PROPUESTA. TODA LA EXPERIENCIA.', 'ONE OFFER. THE COMPLETE EXPERIENCE.')}</span><h2 id="offer-heading">{t('De la primera mirada<br>a la <em>consulta comercial.</em>', 'From the first look<br>to the <em>sales enquiry.</em>')}</h2><p>{t('Adaptamos esta experiencia a tu proyecto para que tus compradores puedan explorar, elegir y llegar a tu equipo con una vivienda en mente.', 'We adapt this experience to your project so buyers can explore, choose and reach your team with a home in mind.')}</p></div>'''
    return f'''<section class="offer-section" id="inversion" aria-label="Propuesta e inversión / Offer and investment">
{heading if show_intro else ''}
      <div class="offer-grid"><div class="offer-scope"><h3 class="scope-heading">{t('Lo que recibe tu proyecto', 'What your project receives')}</h3><ol>{scope}</ol></div>
      <aside class="investment" aria-label="Inversión / Investment"><span class="eyebrow">{t('EXPERIENCIA INMOBILIARIA 3D', '3D REAL ESTATE EXPERIENCE')}</span><div class="offer-price"><span>US$</span><strong>{OFFER_TOTAL}</strong></div><p class="tax-note">{t('Precio total · IVA incluido', 'Total price · VAT included')}</p><div class="investment-rule"></div><p class="offer-definition">{t('Una implementación.<br>Un proyecto inmobiliario.<br>Una experiencia completa.', 'One implementation.<br>One real estate project.<br>One complete experience.')}</p>{enquiry_link()}<a class="offer-demo" href="/proyecto/">{t('Explorar la demo antes de decidir', 'Explore the demo before deciding')} →</a><p class="investment-note">{t('Envía tu proyecto desde el formulario y recibe una confirmación con número de referencia.', 'Submit your project through the form and receive a confirmation with a reference number.')}</p></aside></div>
      <div class="offer-process"><div><span class="eyebrow">{t('ASÍ LO LLEVAMOS A TU PROYECTO', 'HOW WE BRING IT TO YOUR PROJECT')}</span><h2>{t('Tres pasos.<br> <em>Un mismo objetivo.</em>', 'Three steps.<br> <em>One shared goal.</em>')}</h2></div><ol><li><b>01 / {t('Definimos', 'Define')}</b><p>{t('Revisamos marca, planos, inventario y materiales 3D. Acordamos el alcance, las fechas y la forma de pago.', 'We review your brand, plans, inventory and 3D materials, then agree on scope, dates and payment terms.')}</p></li><li><b>02 / {t('Adaptamos', 'Adapt')}</b><p>{t('Preparamos el sitio y el recorrido. Tu equipo valida los espacios, la información y los contactos.', 'We prepare the site and tour. Your team validates the spaces, information and contacts.')}</p></li><li><b>03 / {t('Publicamos', 'Publish')}</b><p>{t('Revisamos la experiencia en móvil y escritorio y dejamos listo el enlace para tus campañas y asesores.', 'We review the mobile and desktop experience and prepare the link for your campaigns and sales team.')}</p></li></ol></div>
      <div class="offer-notes"><div><h3>{t('Para preparar tu proyecto', 'To prepare your project')}</h3><p>{t('Tu equipo entrega marca, textos ES/EN, inventario y modelos 3D listos para web (GLB/glTF). Revisamos su compatibilidad antes de aceptar el proyecto. La creación desde planos, remodelación geométrica, materiales personalizados y renders fotorrealistas se cotizan aparte.', 'Your team supplies branding, ES/EN copy, inventory and web-ready 3D models (GLB/glTF). We review compatibility before accepting the project. Modelling from drawings, geometry reconstruction, custom materials and photorealistic renders are quoted separately.')}</p></div><div><h3>{t('Alcance y condiciones', 'Scope and terms')}</h3><p>{t('Un proyecto, hasta 2 tipologías y 100 unidades. Dominio, hosting, licencias, CRM, WhatsApp e inventario sincronizado no están incluidos. Incluye formulario con bandeja privada y entrega de código fuente. La proforma personalizada tiene una vigencia de 15 días.', 'One project, up to 2 apartment types and 100 units. Domain, hosting, licences, CRM, WhatsApp and synchronized inventory are excluded. Includes a form with a private inbox and source-code handover. A personalised proforma is valid for 15 days.')}</p></div></div>
      <div class="delivery-terms"><div><h3>{t('Entrega y revisiones', 'Delivery and reviews')}</h3><p>{t('10 días laborables desde el anticipo y la recepción de todos los materiales aprobados. Incluye 2 rondas de ajustes consolidados dentro del alcance. El plazo se pausa mientras esperamos comentarios o materiales.', '10 business days from the deposit and receipt of all approved materials. Includes 2 consolidated review rounds within scope. The schedule pauses while awaiting feedback or materials.')}</p></div><div><h3>{t('Pago y acompañamiento', 'Payment and support')}</h3><p>{t('Anticipo: US$499.00. Saldo: US$498.99 tras aprobar la entrega y antes de publicar. Ambos incluyen IVA. Corrección de errores del alcance durante 30 días desde la publicación; nuevas funciones y actualizaciones de contenido se cotizan aparte.', 'Deposit: US$499.00. Balance: US$498.99 after delivery approval and before launch. Both include VAT. In-scope bug fixes for 30 days after launch; new features and content updates are quoted separately.')}</p></div></div>
      <p class="offer-disclosure">{t('Residencia 01 es una demostración ficticia. La gestión de inventario y las conexiones CRM/WhatsApp de la demo son simulaciones; el formulario de contacto sí registra consultas. Esta proforma es una propuesta comercial y no una factura.', 'Residencia 01 is a fictional demonstration. The demo inventory manager and CRM/WhatsApp connections are simulations; the contact form does save enquiries. This proforma is a commercial proposal, not an invoice.')}</p>
    </section>'''


def proforma_body():
    return f'''<main id="main" class="commercial-proforma"><div class="proforma-masthead"><div><span class="eyebrow">ANDEAN SOFTWARE LAB / {t('PROPUESTA COMERCIAL', 'COMMERCIAL PROPOSAL')}</span><h1>{t('Tu próxima<br><em>herramienta de venta.</em>', 'Your next<br><em>sales tool.</em>')}</h1><p>{t('Sitio inmobiliario con recorrido 3D para un proyecto.', 'A real estate website with a 3D journey for one project.')}</p></div><div class="proforma-actions"><button class="button" id="print-proforma" type="button">{t('Imprimir / guardar PDF', 'Print / save PDF')} ↗</button><a class="text-button" href="/proyecto/">{t('Ver la experiencia 3D', 'See the 3D experience')} →</a></div></div>{offer(False)}<div class="proforma-contact"><b>ANDEAN SOFTWARE LAB</b><span>Alvaro Paz · alvaroipazr@gmail.com</span><span>Martín Vélez Falconí · martinvelezf@hotmail.com</span><a href="https://inmobiliaria.alvaropaz.com/proyecto/">inmobiliaria.alvaropaz.com</a></div></main>'''
